```java
public static int fee(int minutes) {
    if (minutes <= 30) {
        return 0;
    }
    int hours = (minutes + 59) / 60;
    int cost = hours * 2;
    if (cost > 12) {
        cost = 12;
    }
    return cost;
}
```

```java
public static int longestStay(int budget) {
    for (int m = 1440; m >= 0; m--) {
        if (fee(m) <= budget) {
            return m;
        }
    }
    return 0;
}
```

```java
public class ScoreKeeper {
    private static int totalScores = 0;
    private String name;
    private int sum;
    private int count;
    private int best;
    public ScoreKeeper(String name) {
        this.name = name;
        best = -1;
    }
    public void addScore(int s) {
        sum += s;
        count++;
        totalScores++;
        if (s > best) {
            best = s;
        }
    }
    public double getAverage() {
        if (count == 0) {
            return 0.0;
        }
        return (double) sum / count;
    }
    public int getBest() {
        return best;
    }
    public static int getTotalScores() {
        return totalScores;
    }
}
```

```java
public int totalTime(String artist) {
    int total = 0;
    for (Song s : songs) {
        if (s.getArtist().equals(artist)) {
            total += s.getSeconds();
        }
    }
    return total;
}
```

```java
public int removeShort(int min) {
    int removed = 0;
    for (int i = songs.size() - 1; i >= 0; i--) {
        if (songs.get(i).getSeconds() < min) {
            songs.remove(i);
            removed++;
        }
    }
    return removed;
}
```

```java
public double testAverage(int c) {
    int sum = 0;
    for (int r = 0; r < scores.length; r++) {
        sum += scores[r][c];
    }
    return (double) sum / scores.length;
}
```

```java
public int mostImproved() {
    int last = scores[0].length - 1;
    int best = 0;
    int bestDiff = scores[0][last] - scores[0][0];
    for (int r = 1; r < scores.length; r++) {
        int diff = scores[r][last] - scores[r][0];
        if (diff > bestDiff) {
            bestDiff = diff;
            best = r;
        }
    }
    return best;
}
```
